//! No agent co-author line by default (unless the user
//! switches it on): Vibe Work's own `VIBE_HOME/config.toml` gets `include_commit_signature = false` unless it already
//! sets that key.
//!
//! Why: while the key is true (Vibe's default, `vibe_schema.py:652`), Vibe's system prompt tells the agent to end every
//! commit message with "Generated by Mistral Vibe." and "Co-Authored-By: Mistral Vibe <vibe@mistral.ai>"
//! (`core/system_prompt.py:433`, `app_server/_runtime.py:266`), so agent commits carry it, as does the
//! pull request text Vibe Work drafts from those commits. The credit line is the user's choice: our Commit
//! dialog has a per-project switch for the user's own commits (unchanged); this does the same for the agent's.
//!
//! The user's own switch keeps working: a config that already sets `include_commit_signature` (true or false, the user's
//! edit or ours from an earlier start) is left as it is; writing `include_commit_signature = true` there turns the
//! agent's credit line back on.
//!
//! Depends on: `toml` (parsing only; the file is edited as text so the user's comments and layout stay).
//! Called by: `launch` (product and development launches, before the server starts), tests.
//! Invariants: only Vibe Work's own `VIBE_HOME` (never `~/.vibe`); a file that is not valid TOML is left byte-identical;
//! the edit is verified (the new file parses and equals the old data plus this one key) before a temp-file rename.

use std::path::Path;

use toml::{Table, Value};

/// The key (top level of Vibe's config).
pub const KEY: &str = "include_commit_signature";

/// The lines written above the key (English, no paths; they ship into the user's config).
const NOTE: [&str; 2] = [
    "# Vibe Work: the agent's commits carry no \"Co-Authored-By: Mistral Vibe\" line unless you set this to true.",
    "# (Your own commits: the Commit dialog's credit switch, per project.)",
];

/// What [`ensure`] did.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CommitSignature {
    /// `include_commit_signature = false` was added.
    Added,
    /// The config already sets the key (to this value): left as it is.
    Kept(bool),
    /// Left unchanged, with the reason.
    Skipped(String),
}

/// The config text with `include_commit_signature = false` added at the top (top-level keys must come before the
/// first table), or the outcome when nothing is to be written. Pure.
///
/// # Errors
/// `Kept` / `Skipped` when the text stays as it is.
pub fn with_default_off(existing: &str) -> Result<String, CommitSignature> {
    let before: Table = existing.parse().map_err(|_| {
        CommitSignature::Skipped(
            "config.toml is not valid TOML; Vibe reports the error itself".to_owned(),
        )
    })?;
    if let Some(value) = before.get(KEY) {
        return Err(value.as_bool().map_or_else(
            || CommitSignature::Skipped(format!("{KEY} is not true or false")),
            CommitSignature::Kept,
        ));
    }
    let newline = if existing.contains("\r\n") {
        "\r\n"
    } else {
        "\n"
    };
    let mut out = String::with_capacity(existing.len() + 200);
    for line in NOTE {
        out.push_str(line);
        out.push_str(newline);
    }
    out.push_str(KEY);
    out.push_str(" = false");
    out.push_str(newline);
    if !existing.is_empty() {
        out.push_str(newline);
        out.push_str(existing);
    }
    let Ok(mut after) = out.parse::<Table>() else {
        return Err(CommitSignature::Skipped(
            "the edit could not be verified".to_owned(),
        ));
    };
    if after.remove(KEY) != Some(Value::Boolean(false)) || after != before {
        return Err(CommitSignature::Skipped(
            "the edit could not be verified".to_owned(),
        ));
    }
    Ok(out)
}

/// Makes `vibe_home/config.toml` set `include_commit_signature` (false unless already set). A missing file is created.
///
/// # Errors
/// The I/O error text when the file cannot be read or written.
pub fn ensure(vibe_home: &Path) -> Result<CommitSignature, String> {
    let path = vibe_home.join("config.toml");
    let existing = match std::fs::read_to_string(&path) {
        Ok(text) => text,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => String::new(),
        Err(e) => return Err(format!("{}: {e}", path.display())),
    };
    let updated = match with_default_off(&existing) {
        Ok(text) => text,
        Err(outcome) => return Ok(outcome),
    };
    std::fs::create_dir_all(vibe_home).map_err(|e| format!("{}: {e}", vibe_home.display()))?;
    let tmp = vibe_home.join("config.toml.vw-tmp");
    std::fs::write(&tmp, &updated).map_err(|e| format!("{}: {e}", tmp.display()))?;
    std::fs::rename(&tmp, &path).map_err(|e| {
        let _ = std::fs::remove_file(&tmp);
        format!("{}: {e}", path.display())
    })?;
    Ok(CommitSignature::Added)
}
